={{ {
  "model": "sonar-pro",
  "messages": [
    {
      "role": "system",
      "content": "You are a sports technology research scout. Find the most recent, specific developments from the last 72 hours. Focus on concrete events: new research papers, product launches, funding rounds, partnerships, injuries to high-profile athletes, or regulatory changes. Be specific with names, dates, and sources."
    },
    {
      "role": "user",
      "content": $json.query
    }
  ],
  "temperature": 0.1
} }}

={{ {
  "system_instruction": {
    "parts": [{
      "text": "You are the Intelligence Scout for Synthetix AI and CloudPulse.

Evaluate the provided research data and extract concrete signals.

CRITICAL VERIFICATION LAYER:
You MUST evaluate the credibility of the information. Do not forward speculative AI hallucinations.
For each signal, you must provide:
- source_credibility: MUST be exactly one of ['peer_reviewed', 'institutional', 'news_major', 'social', 'speculative']
- evidence_level: MUST be exactly one of ['verified', 'claimed', 'rumor']

Return a JSON array:
[{
  "title": "concise signal title",
  "summary": "2-3 sentences explaining the signal",
  "source": "url or entity",
  "product": "synthetix_ai" | "cloudpulse_saas" | "aura_commerce",
  "signal_type": "market_trend" | "competitor_move" | "research_study",
  "relevance_score": 0-100,
  "confidence_score": 0-100,
  "source_credibility": "...",
  "evidence_level": "..."
}]

Return ONLY the JSON array. Dismiss any signal that is just general industry fluff."
    }]
  },
  "contents": [{
    "parts": [{
      "text": "Research Data:
" + $json.choices[0].message.content
    }]
  }],
  "generationConfig": {
    "temperature": 0.1,
    "responseMimeType": "application/json"
  }
} }}

parameters.jsCode:
try {
  const raw = $json.candidates[0].content.parts[0].text;
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  const signals = JSON.parse(cleaned);
  const query = $('Loop Queries').item.json.query;
  const category = $('Loop Queries').item.json.category;
  const product = $('Loop Queries').item.json.product || 'synthetix_ai';

  if (!Array.isArray(signals) || signals.length === 0) {
    return { empty: true, query };
  }

  return signals.map(s => ({
    signal_type: 'trend',
    source: 'perplexity',
    source_url: null,
    product: product,
    title: s.title || 'Untitled signal',
    summary: s.summary || '',
    raw_data: JSON.stringify({ query, category, suggested_action: s.suggested_action }),
    source_credibility: s.source_credibility || 'unknown',
    evidence_level: s.evidence_level || 'unverified',
    relevance_score: Math.min(100, Math.max(0, s.relevance_score || 50)),
    confidence_score: Math.min(100, Math.max(0, s.confidence_score || 50))
  }));
} catch (e) {
  return { empty: true, error: e.message };
}

